import React, { useEffect, useState } from "react";
import axios from "axios";
import { Link } from "react-router-dom";

const EmployeeList = () => {
  const [employees, setEmployees] = useState([]);

  const fetchEmployees = async () => {
    const res = await axios.get("http://localhost:8080/api/employees/all");
    setEmployees(res.data);
  };

  const deleteEmployee = async (id) => {
    await axios.delete(`http://localhost:8080/api/employees/${id}`);
    fetchEmployees();
  };

  useEffect(() => {
    fetchEmployees();
  }, []);

  return (
    <div className="container">
      <Link to="/add" className="btn btn-primary">
        Add Employee
      </Link>
      <h2>Employee List</h2>
      {/* <ul>
        {employees.map((emp) => (
          <li key={emp.id}>
            {emp.name} - {emp.lastname} - {emp.email} - {emp.position}
            <button onClick={() => deleteEmployee(emp.id)}>Delete</button>
            <Link to={`/edit/${emp.id}`}>Edit</Link>
          </li>
        ))}
      </ul> */}
      <DataTable
        value={employees}
        paginator
        rows={5}
        rowsPerPageOptions={[5, 10, 20]}
        responsiveLayout="scroll"
        stripedRows
        tableStyle={{ minWidth: "50rem" }}
      >
        <Column field="name" header="Name" sortable />
        <Column field="lastname" header="Last Name" sortable />
        <Column field="email" header="Email" sortable />
        <Column field="position" header="Position" sortable />
        <Column body={editBodyTemplate} header="Edit" />
        <Column body={deleteBodyTemplate} header="Delete" />
      </DataTable>
    </div>
  );
};

export default EmployeeList;
